import{_ as a,c as o,o as r,ah as t}from"./chunks/framework.BaqsfJuc.js";const h=JSON.parse('{"title":"Protocol Conformance Tests (v0.1 plan)","description":"","frontmatter":{},"headers":[],"relativePath":"specs/protocol-conformance-tests.md","filePath":"specs/protocol-conformance-tests.md","lastUpdated":1763898043000}'),s={name:"specs/protocol-conformance-tests.md"};function i(n,e,d,c,l,m){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="protocol-conformance-tests-v0-1-plan" tabindex="-1">Protocol Conformance Tests (v0.1 plan) <a class="header-anchor" href="#protocol-conformance-tests-v0-1-plan" aria-label="Permalink to “Protocol Conformance Tests (v0.1 plan)”">​</a></h1><p>Lightweight checklist for cross-implementation compatibility. Use deterministic fixtures; avoid network in golden tests.</p><h2 id="fixtures" tabindex="-1">Fixtures <a class="header-anchor" href="#fixtures" aria-label="Permalink to “Fixtures”">​</a></h2><ul><li>Frame vectors: encode/decode golden cases for each frame kind (with fixed 16-byte <code>frameId</code> values), using fixed inputs for <code>subject</code>, <code>body</code>, <code>message</code>, <code>ackId</code>, <code>code</code>.</li><li>Handshake payloads: valid base case; invalid protocol/version; missing <code>peerId</code>; oversized metadata.</li><li>Error cases: malformed headers (short buffer, bad lengths), invalid frameId length (not 16 bytes), reserved flag bits set, unknown frame kind, incomplete payload for each frame kind.</li></ul><h2 id="invariants-to-assert" tabindex="-1">Invariants to assert <a class="header-anchor" href="#invariants-to-assert" aria-label="Permalink to “Invariants to assert”">​</a></h2><ul><li>Round-trip encoding: <code>decode(encode(frame))</code> yields the same structure for all supported frames.</li><li>Frame ID validity: <code>frameId</code> MUST be exactly 16 bytes (opaque binary). Equality checked by byte-wise comparison.</li><li>Reserved bits: any non-zero reserved flag bit MUST throw <code>InvalidFrame</code>.</li><li>Length guards: subject length mismatch and message length mismatch MUST throw <code>InvalidFrame</code>.</li><li>Handshake validation: wrong protocol/version MUST throw <code>UnsupportedVersion</code>; missing required fields MUST throw <code>InvalidFrame</code>.</li><li>Ack frame ID: must reference exactly 16 bytes from another frame&#39;s <code>frameId</code>.</li></ul><h2 id="negative-fuzzing" tabindex="-1">Negative fuzzing <a class="header-anchor" href="#negative-fuzzing" aria-label="Permalink to “Negative fuzzing”">​</a></h2><ul><li>Feed random/oversized buffers into <code>decodeFrame</code>; expect bounded error handling (no crashes/hangs) and <code>InvalidFrame</code>.</li><li>Bound <code>ErrorFrame.message</code> length to implementation limit; ensure rejection path is consistent.</li></ul><h2 id="transport-shared-expectations" tabindex="-1">Transport-shared expectations <a class="header-anchor" href="#transport-shared-expectations" aria-label="Permalink to “Transport-shared expectations”">​</a></h2><ul><li>Ordering: encoded frame sequences preserve order after decode.</li><li>Unicode: subjects/messages are UTF-8; invalid UTF-8 MUST be rejected when decoded to string fields.</li><li>Limits: frames exceeding configured size caps MUST yield <code>ProtocolViolation</code> and closure.</li></ul>',10)])])}const p=a(s,[["render",i]]);export{h as __pageData,p as default};
